class TFMLogicBlockCustomBaseBlock extends TFMLogicBlock implements TFMLogicBlockDataCollectionInterface
{

    TFMRegistrationCollectors       regCols;
    TFMRegistrationCollectors       prePostCols;
    TFMCustomLogicBlockName         theBlockName;
    TFMImageName                    iconName;

}

Method.Source:
/// <summary>
/// This method provides the header fields, that are needed to find out which data should be collected.
/// </summary>
/// <returns>A TFMReferenceDataConfiguration object, containing registration collectors for the header.</returns>
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    if (!refConf)
    {
        refConf = new TFMReferenceDataConfiguration();
    }
    return refConf;
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    if (!regCols)
    {
        regCols = TFMRegistrationCollectors::Construct();
    }
    return regCols;
}

/// <summary>
/// This method is called before the post method, and gives the option to add extra registration collectors for the user to be prompted for before the post method is executed.
/// </summary>
/// <returns>Returns a TFMRegistrationCollectors object if the user must be further prompted, otherwise it returns null</returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    //Online Steps
    if (!prePostCols)
    {
        prePostCols = TFMRegistrationCollectors::Construct();
    }
    return prePostCols;
}

/// <summary>
/// The method executed when all data has been collected, and contains the posting logic.
/// </summary>
/// <returns>A TFMPostResponseData object.</returns>
public TFMPostResponseData post()
{
    return TFMPostResponseData::Construct();
}

[TFMParameter('')]
public TFMCustomLogicBlockName parmCustomBlock(TFMCustomLogicBlockName _blockName = theBlockName)
{
    theBlockName = _blockName;
    if (!prmIsDefault(_blockName))
    {
        this.loadCustomBlock();
    }
    return theBlockName;
}

protected void loadCustomBlock()
{
    TFMCustomBlockSteps steps;
    TFMCustomBlocks blockTable = TFMCustomBlocks::Find(theBlockName);
    TFMRegistrationCollector col;
    int i;
    while select steps where steps.BlockName == theBlockName
    {
        col = new SysDictClass(className2Id(steps.ClassName)).makeObject(i,steps.Name,steps.Name,steps.Name,steps.Name);
        col.updateParmsFromOverride('BlockStudio', steps.Name);
        this.registrationCollectors().addCollector(col);
        i++;
    }

    iconName = blockTable.Icon;

}

public str blockIcon()
{
    if (iconName)
    {
        return iconName;
    }

    return super();
}

public Name blockName()
{
    return theBlockName ? theBlockName : "@TFM:CustomBlock";
}
